/**
 * Header.js - Dashboard Header Component
 * Week 2 - Days 10-14
 */

import React from 'react';
import { motion } from 'framer-motion';

const Header = ({ apiHealth }) => {
  const isHealthy = apiHealth?.model_loaded;

  return (
    <header className="header">
      <div className="container">
        <div className="header-content">
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.5 }}
            className="header-title"
          >
            <span style={{ fontSize: '2rem' }}>🤖</span>
            <div>
              <h1>ATHENA</h1>
              <p className="header-subtitle">Explainable AI Stock Prediction</p>
            </div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.5, delay: 0.2 }}
          >
            {apiHealth && (
              <div className="health-indicator">
                <div className={`health-dot ${isHealthy ? 'healthy' : 'unhealthy'}`}></div>
                <span>{isHealthy ? 'Model Ready' : 'Model Offline'}</span>
              </div>
            )}
          </motion.div>
        </div>
      </div>
    </header>
  );
};

export default Header;
